import email.utils
import random
import time


def reference(params):
    """Decode the unencoded RFC 2231 continuations generated by this script."""
    groups = {}
    for attribute, value in params[1:]:
        base, number = attribute.rsplit("*", 1)
        groups.setdefault(base.lower(), []).append((int(number), value))

    result = [params[0]]
    for base, segments in groups.items():
        segments.sort(key=lambda segment: segment[0])
        assert [number for number, _ in segments] == list(range(len(segments)))
        value = "".join(value for _, value in segments)
        result.append((base, '"' + value + '"'))
    return result


def canonical(result):
    return [result[0]] + [
        (name.lower(), value) for name, value in result[1:]
    ]


def evaluate(params):
    try:
        return email.utils.decode_params(params[:])
    except Exception as exc:
        return ("EXCEPTION", type(exc).__name__, str(exc))


def matches(actual, expected):
    return isinstance(actual, list) and canonical(actual) == canonical(expected)


def main():
    deadline = time.monotonic() + 175
    ordinary = [
        [("text/plain", ""), ("filename*0", "report"), ("filename*1", ".txt")],
        [
            ("text/plain", ""),
            ("title*0", "one"),
            ("title*1", "-two"),
            ("title*2", "-three"),
        ],
    ]
    for index, params in enumerate(ordinary, 1):
        expected = reference(params)
        actual = evaluate(params)
        print("SANITY", index, "actual:", repr(actual), "expected:", repr(expected))
        if not matches(actual, expected):
            print("SANITY FAILED")
            return

    tested = 0

    def check(params):
        nonlocal tested
        tested += 1
        expected = reference(params)
        actual = evaluate(params)
        if matches(actual, expected):
            return False
        repeated = evaluate(params)
        if repeated != actual or matches(repeated, expected):
            return False
        print("COUNTEREXAMPLE:")
        print(repr(params))
        print("actual:", repr(repeated))
        print("expected:", repr(expected))
        return True

    edges = [
        [("text/plain", ""), ("filename*0", "report"), ("FILENAME*1", ".txt")],
        [("text/plain", ""), ("FILENAME*0", "a"), ("filename*1", "b")],
        [
            ("text/plain", ""),
            ("Name*0", "a"),
            ("nAME*1", "b"),
            ("NAME*2", "c"),
        ],
        [("text/plain", "")] + [
            (("filename" if i % 2 == 0 else "FILENAME") + "*" + str(i), "x")
            for i in range(12)
        ],
    ]
    for params in edges:
        if check(params):
            return

    rng = random.Random(2231)
    alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"
    while time.monotonic() < deadline:
        base = rng.choice(["filename", "title", "name", "description"])
        count = rng.randint(2, 24)
        params = [("text/plain", "")]
        for i in range(count):
            attribute = "".join(
                letter.upper() if rng.randrange(2) else letter.lower()
                for letter in base
            )
            value = "".join(
                rng.choice(alphabet) for _ in range(rng.randint(1, 30))
            )
            params.append((attribute + "*" + str(i), value))
        if check(params):
            return

    print("NO COUNTEREXAMPLE", tested)


if __name__ == "__main__":
    main()